// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor) public {
        // actor must be a non-contract address that never locked a guess
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        bool ok = true;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference C requires a prior lock (guesses[actor].block != 0) and therefore
        // always reverts for an address that never locked. Mutant M replaces that
        // require with require(true), so settle() on a never-locked address succeeds.
        assertTrue(ok == false);
    }
}
